#!/usr/bin/env node
// Fix up the dist/package.json generated by `@effect/build-utils pack-v3` so the
// published tarball matches what actually ships. Two corrections:
//
// 1. Resolve the `workspace:` protocol into concrete semver ranges. This repo
//    packs with `npm pack` on the build-utils `dist/` folder and publishes the
//    resulting tarball with `npm publish`. Neither npm step understands
//    `workspace:`, so without this the published manifest ships literal
//    `workspace:^` and consumers hit EUNSUPPORTEDPROTOCOL. (yarn/pnpm only
//    rewrite the protocol when publishing a workspace member directly, which
//    this dist-based flow never does.)
//
// 2. Drop the CommonJS export conditions. pack-v3 writes a
//    `"default": "./dist/cjs/<module>.js"` condition into every export
//    unconditionally, without checking whether a `build/cjs` directory was
//    produced. These packages are ESM only, so those files are not in the
//    tarball and `require()` — or any resolver that picks `default` ahead of
//    `import` — resolves to a missing file. Collapsing each export to its ESM
//    target leaves `import` working as before, while `require()` either loads it
//    via Node's require(esm) support or fails with a clear ERR_REQUIRE_ESM.
//
// Usage: node scripts/finalize-dist-manifest.mjs <path-to-dist/package.json>

import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const target = process.argv[2];
if (!target) {
  console.error('usage: finalize-dist-manifest.mjs <dist/package.json>');
  process.exit(1);
}

// Repo root is the parent of this script's `scripts/` directory.
const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');

// Map workspace package name -> version by scanning top-level dirs
// (the root `workspaces` glob is "*").
const versions = new Map();
for (const entry of readdirSync(repoRoot, { withFileTypes: true })) {
  if (!entry.isDirectory()) continue;
  const pkgPath = join(repoRoot, entry.name, 'package.json');
  if (!existsSync(pkgPath)) continue;
  try {
    const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
    if (pkg.name && pkg.version) versions.set(pkg.name, pkg.version);
  } catch {
    /* ignore non-JSON / unreadable */
  }
}

const resolveRange = (name, spec) => {
  // spec is e.g. "workspace:^", "workspace:~", "workspace:*", "workspace:^1.2.3"
  const rest = spec.slice('workspace:'.length);
  const version = versions.get(name);
  if (!version) {
    throw new Error(`cannot resolve workspace dependency "${name}": not found in workspace`);
  }
  if (rest === '' || rest === '*') return version; // exact
  if (rest === '^') return `^${version}`;
  if (rest === '~') return `~${version}`;
  return rest; // explicit range already, e.g. "^1.2.3"
};

const manifest = JSON.parse(readFileSync(target, 'utf8'));

for (const field of ['dependencies', 'peerDependencies', 'optionalDependencies', 'devDependencies']) {
  const deps = manifest[field];
  if (!deps) continue;
  for (const [name, spec] of Object.entries(deps)) {
    if (typeof spec === 'string' && spec.startsWith('workspace:')) {
      deps[name] = resolveRange(name, spec);
      console.log(`  ${field}: ${name}  ${spec} -> ${deps[name]}`);
    }
  }
}

for (const [entry, conditions] of Object.entries(manifest.exports ?? {})) {
  // `./package.json` (and any other direct file mapping) is a plain string.
  if (typeof conditions !== 'object' || conditions === null) continue;
  if (typeof conditions.import !== 'string') continue;

  manifest.exports[entry] = {
    ...(conditions.types === undefined ? {} : { types: conditions.types }),
    default: conditions.import
  };
  console.log(`  exports["${entry}"]: -> ${conditions.import}`);
}

// `module` only carries meaning alongside a CJS `main`; pack-v3 omits it for
// ESM-only packages, but drop it defensively so the two can never disagree.
delete manifest.module;

const serialized = JSON.stringify(manifest, null, 2) + '\n';
if (serialized.includes('/dist/cjs/')) {
  console.error(`${target} still references ./dist/cjs after rewriting`);
  process.exit(1);
}

writeFileSync(target, serialized);
console.log(`finalized ${target}`);
